	@Test
	void projectionAuxiliaryExpressionAndContextBelongToThePrivateGraph() {
		ExtensionElem expression = new ExtensionElem(new ValueConstant(VF.createLiteral("owned")), "v");
		Extension extension = new Extension(new SingletonSet(), expression);
		ProjectionElem element = new ProjectionElem("v");
		element.setSourceExpression(expression);
		Projection projection = new Projection(extension, new ProjectionElemList(element));
		Var context = Var.of("context", VF.createIRI("urn:owned:graph")).withApiInputOrigin();
		context.setGraphContextDepth(3);
		projection.setProjectionContext(context);
		QueryRoot source = new QueryRoot(projection);
		PlanningGraphDomains.capture(source, PlanningGraphDomain.defaultGraph());
		QueryRoot detached = assertInstanceOf(QueryRoot.class, LmdbCacheValueCopies.copy(source, false));
		Projection copy = assertInstanceOf(Projection.class, detached.getArg());
		Extension privateExtension = assertInstanceOf(Extension.class, copy.getArg());
		assertSame(privateExtension.getElements().get(0),
				copy.getProjectionElemList().getElements().get(0).getSourceExpression());
		assertNotSame(expression, copy.getProjectionElemList().getElements().get(0).getSourceExpression());
		assertNotSame(context, copy.getProjectionContext());
		assertEquals(3, copy.getProjectionContext().getGraphContextDepth());
		assertTrue(copy.getProjectionContext().hasApiInputOrigin());
		assertEquals(PlanningGraphDomains.domain(projection), PlanningGraphDomains.domain(copy));
		expression.setExpr(new ValueConstant(VF.createLiteral("changed")));
		assertEquals(VF.createLiteral("owned"), assertInstanceOf(ValueConstant.class,
				privateExtension.getElements().get(0).getExpr()).getValue());
	}

	@Test
	void externalProjectionSourceExpressionRemainsExternalAndCacheCopyDeclinesWithoutVisitingItsOwner() {
		ExtensionElem external = new ExtensionElem(new ValueConstant(VF.createLiteral("outside")), "outside");
		ObservedExternalExtension externalOwner = new ObservedExternalExtension(external);
		ProjectionElem element = new ProjectionElem("outside");
		element.setSourceExpression(external);
		QueryRoot source = new QueryRoot(
				new Projection(new SingletonSet(), new ProjectionElemList(element)));

		QueryRoot cloned = source.clone();
		ProjectionElem clonedElement = ((Projection) cloned.getArg()).getProjectionElemList().getElements().get(0);
		assertSame(external, clonedElement.getSourceExpression());
		assertSame(externalOwner, clonedElement.getSourceExpression().getParentNode());
		assertNull(LmdbCacheValueCopies.copy(cloned, false));
		assertEquals(0, externalOwner.childVisits,
				"declining an externally parented projection expression must not visit its external owner");
	}

	@Test
	void parsedMedicalAndNestedAggregateQueriesRetainOwnedProjectionAliasesAcrossCloneAndCacheCopy() {
		for (String queryText : List.of(MEDICAL_Q10, NESTED_AGGREGATE_QUERY)) {
			TupleExpr original = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, queryText, null).getTupleExpr();
			TupleExpr cloned = original.clone();
			assertAll(queryText,
					() -> assertOwnedProjectionSourceExpressionsFollowTheirClonedOwners(original, cloned, queryText),
					() -> assertNotNull(LmdbCacheValueCopies.copy(cloned, false),
							"an owned parsed projection source expression must remain cache-copyable"));
		}
	}

	@Test
	void repeatedFreshMedicalQ10QueriesHitThePipelineCacheForBothInferenceModes(@TempDir Path directory)
			throws Exception {
		var config = new LmdbStoreConfig("spoc,ospc,posc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL);
		config.setExperimentalQueryOptimizations(true);
		SailRepository repository = new SailRepository(
				new LmdbStore(directory.resolve("medical-q10").toFile(), config));
		repository.init();
		try {
			seedMedicalQ10(repository);
			LmdbTestUtil.awaitPostReadyInitialization((LmdbStore) repository.getSail(), 30L,
					java.util.concurrent.TimeUnit.SECONDS);
			LmdbStore store = (LmdbStore) repository.getSail();
			if (!store.getBackingStore().directAdjacencyStore().rebuildNowForTest()) {
				fail("could not prepare direct adjacency for MEDICAL_RECORDS query 10");
			}
			assertTrue(store.awaitDirectAdjacencyReady(30L, java.util.concurrent.TimeUnit.SECONDS),
					store.getDirectAdjacencyReadinessDescription());

			for (boolean includeInferred : new boolean[] { false, true }) {
				for (int iteration = 1; iteration <= 2; iteration++) {
					try (var connection = repository.getConnection()) {
						TupleQuery query = connection.prepareTupleQuery(MEDICAL_Q10);
						query.setIncludeInferred(includeInferred);
						TupleExpr optimized = (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
						if (iteration == 2) {
							assertEquals("true", optimized.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
									"second fresh q10 preparation should hit for includeInferred=" + includeInferred);
						}
						try (var rows = query.evaluate()) {
							assertTrue(rows.hasNext());
							assertEquals("1", rows.next().getValue("count").stringValue());
							assertFalse(rows.hasNext());
						}
					}
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void valuesHeaderUndefRowsAndFrameRemainIndependentFromCallerCollections() {
		BindingSetAssignment assignment = new BindingSetAssignment();
		Set<String> header = new LinkedHashSet<>(List.of("v", "undef"));
		List<BindingSet> rows = new ArrayList<>();
		rows.add(new ListBindingSet(List.of("v", "undef"), VF.createLiteral("row"), null));
		assignment.setBindingNames(header);
		assignment.setBindingSets(rows);
		assignment.setIndependentInputScope(true);
		assignment.setVariableScopeChange(true);
		QueryRoot detached = assertInstanceOf(QueryRoot.class,
				LmdbCacheValueCopies.copy(new QueryRoot(assignment), false));
		BindingSetAssignment copy = assertInstanceOf(BindingSetAssignment.class, detached.getArg());
		header.add("later");
		rows.clear();
		assertEquals(Set.of("v", "undef"), copy.getDeclaredBindingNames());
		assertEquals(Set.of("v"), copy.getPossibleBindingNames());
		assertEquals(Set.of("v"), copy.getAssuredBindingNames());
		assertTrue(copy.isIndependentInputScope());
		assertTrue(copy.isVariableScopeChange());
		BindingSet row = copy.getBindingSets().iterator().next();
		assertEquals(VF.createLiteral("row"), row.getValue("v"));
		assertNull(row.getValue("undef"));
	}

