	private static StatementPattern pattern() {
		return new StatementPattern(new Var("s"), Var.of("p", P), new Var("o"));
	}

	private static void assertOwnedProjectionSourceExpressionsFollowTheirClonedOwners(TupleExpr source,
			TupleExpr cloned, String label) {
		List<ProjectionElem> sourceProjectionElements = projectionElements(source);
		List<ProjectionElem> clonedProjectionElements = projectionElements(cloned);
		assertEquals(sourceProjectionElements.size(), clonedProjectionElements.size(), label);

		Set<ExtensionElem> sourceOwned = Collections.newSetFromMap(new IdentityHashMap<>());
		sourceOwned.addAll(extensionElements(source));
		Set<ExtensionElem> clonedOwned = Collections.newSetFromMap(new IdentityHashMap<>());
		clonedOwned.addAll(extensionElements(cloned));
		Map<ExtensionElem, ExtensionElem> aliases = new IdentityHashMap<>();
		for (int i = 0; i < sourceProjectionElements.size(); i++) {
			ExtensionElem sourceExpression = sourceProjectionElements.get(i).getSourceExpression();
			ExtensionElem clonedExpression = clonedProjectionElements.get(i).getSourceExpression();
			if (sourceExpression == null) {
				assertNull(clonedExpression, label + " projection index " + i);
			} else if (sourceOwned.contains(sourceExpression)) {
				assertNotNull(clonedExpression, label + " owned projection source expression at index " + i);
				assertFalse(sourceOwned.contains(clonedExpression),
						label + " projection index " + i + " still references the source graph");
				assertTrue(clonedOwned.contains(clonedExpression),
						label + " projection index " + i + " must reference an element owned by the cloned graph");
				ExtensionElem priorAlias = aliases.putIfAbsent(sourceExpression, clonedExpression);
				if (priorAlias != null) {
					assertSame(priorAlias, clonedExpression,
							label + " projection aliases for one owned source expression must remain shared");
				}
			} else {
				assertSame(sourceExpression, clonedExpression,
						label + " unparented or externally parented source expressions retain their original reference");
			}
		}
	}

	private static List<ProjectionElem> projectionElements(TupleExpr expression) {
		List<ProjectionElem> elements = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ProjectionElem element) {
				elements.add(element);
				super.meet(element);
			}
		});
		return elements;
	}

	private static List<ExtensionElem> extensionElements(TupleExpr expression) {
		List<ExtensionElem> elements = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Extension extension) {
				elements.addAll(extension.getElements());
				super.meet(extension);
			}
		});
		return elements;
	}

	private static void seedMedicalQ10(SailRepository repository) {
		var vf = repository.getValueFactory();
		IRI med = vf.createIRI("http://example.com/theme/medical/");
		IRI patient = vf.createIRI("urn:owned:medical:patient");
		IRI medication = vf.createIRI("urn:owned:medical:medication");
		IRI rdfType = vf.createIRI("http://www.w3.org/1999/02/22-rdf-syntax-ns#type");
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(patient, rdfType, vf.createIRI(med.stringValue() + "Patient"));
			connection.add(patient, vf.createIRI(med.stringValue() + "hasMedication"), medication);
			connection.add(patient, vf.createIRI(med.stringValue() + "name"), vf.createLiteral("Patient A"));
			connection.add(medication, rdfType, vf.createIRI(med.stringValue() + "Medication"));
			connection.add(medication, vf.createIRI(med.stringValue() + "code"), vf.createLiteral("MED-1001"));
			connection.commit();
		}
	}

	private static QueryRoot planned() {
		QueryRoot result = new QueryRoot(pattern());
		result.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		return result;
	}

	private static LmdbPipelinePlanCache.Context context() {
		var revision = new LmdbPipelinePlanCache.Revision(new LmdbEstimatorRuntime.PlanningRevisions(17L, 2L, 3L, 4L),
				true);
		return new LmdbPipelinePlanCache.Context(revision, false, 0L, LmdbPipelinePlanCache.DatasetIdentity.of(null),
				LmdbPipelinePlanCache.BindingIdentity.of(EmptyBindingSet.getInstance()), "", false, false, false,
				"STANDARD", false);
	}

	private static final class ObservedExternalExtension extends Extension {
		private int childVisits;

		ObservedExternalExtension(ExtensionElem element) {
			super(new SingletonSet(), element);
		}

		@Override
		public <X extends Exception> void visitChildren(QueryModelVisitor<X> visitor) throws X {
			childVisits++;
			super.visitChildren(visitor);
		}
	}
